import{_ as a,o as e,c as i,a5 as t}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"第4章 アセンブリ ── コンパイラの出力を読む力","description":"","frontmatter":{"title":"第4章 アセンブリ ── コンパイラの出力を読む力","study":{"source":"IT教本","kind":"学習ガイド","status":"学習計画・概要","summary":"アセンブリを書く仕事はほぼないが、読む場面は確実にある: リリースビルドだけで起きるクラッシュの解析、最適化が効いているかの確認、 AI生成コードが本当に速いかの検証、チートやバグの原因究明。"}},"headers":[],"relativePath":"guide/low-level/assembly.md","filePath":"guide/low-level/assembly.md"}'),o={name:"guide/low-level/assembly.md"};function s(n,l,r,d,c,p){return e(),i("div",null,[...l[0]||(l[0]=[t(`<h1 id="第4章-アセンブリ-──-コンパイラの出力を読む力" tabindex="-1">第4章 アセンブリ ── コンパイラの出力を読む力 <a class="header-anchor" href="#第4章-アセンブリ-──-コンパイラの出力を読む力" aria-label="Permalink to &quot;第4章 アセンブリ ── コンパイラの出力を読む力&quot;">​</a></h1><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>アセンブリを<strong>書く</strong>仕事はほぼないが、<strong>読む</strong>場面は確実にある: リリースビルドだけで起きるクラッシュの解析、最適化が効いているかの確認、 AI生成コードが本当に速いかの検証、チートやバグの原因究明。 「Visual Studioでアセンブリまで追える」という最終目標の中核であり、 次章のC言語(ポインタ・関数呼び出し)を一発で理解するための下地でもある。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>x64の主要レジスタ(RAX〜R15, RSP, RBP, RIP, XMM)の役割を言える</li><li>mov/lea/add/cmp/jcc/call/ret/push/pop を読める</li><li>関数呼び出しの仕組み(スタックフレーム、呼出規約)を説明できる</li><li>VSの逆アセンブリウィンドウでC++コードと機械語の対応を追える</li><li>Compiler Explorerで最適化の有無による出力差を読める</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第2章(CPU・命令・レジスタの概念)、第3章(メモリ)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>x64レジスタセット</strong><ul><li>汎用: RAX(戻り値), RCX/RDX/R8/R9(Win引数), RSP(スタックポインタ), RBP, RSI, RDI, R10〜R15</li><li>RIP(命令ポインタ)、RFLAGS(比較結果)</li><li>XMM0〜15(float/SIMD)── floatの引数・戻り値はXMM</li><li>32bit名(EAX)や8bit名(AL)は同じレジスタの部分ビュー</li></ul></li><li><strong>主要命令(これだけで9割読める)</strong><ul><li><code>mov dst, src</code>(転送)、<code>lea</code>(アドレス計算/乗加算の裏技)</li><li><code>add/sub/imul/xor</code>、<code>xor eax,eax</code>=ゼロクリアのイディオム</li><li><code>cmp</code>+<code>je/jne/jl/jg</code>(if文)、<code>jmp</code>(goto)</li><li><code>call/ret</code>、<code>push/pop</code></li><li><code>[rbp-8]</code> などのメモリオペランド記法(スタック上のローカル変数アクセスの一例)</li></ul></li><li><strong>関数呼び出しの完全理解(最重要)</strong><ul><li>スタックは下方向に伸びる。callが戻り番地をpushする</li><li>スタックフレーム: 戻り番地/保存レジスタ/ローカル変数</li><li><strong>Windows x64呼出規約</strong>: 引数はRCX,RDX,R8,R9(浮動小数はXMM0-3)、 5個目以降はスタック、32バイトのshadow space、戻り値はRAX/XMM0</li><li>callee-saved / caller-saved レジスタ</li><li>これが第7章のABIの実体</li></ul></li><li><strong>C構文とアセンブリの対応パターン</strong><ul><li>if/while/for → cmp+jcc の形</li><li>配列アクセス <code>a[i]</code> → <code>mov eax, [rcx+rdx*4]</code></li><li>ポインタ間接参照 → メモリオペランド</li><li>構造体メンバ → ベース+オフセット</li><li>仮想関数呼び出し → vtableポインタのロード+間接call(第9章で再訪)</li></ul></li><li><strong>ツール習熟</strong><ul><li><strong>Compiler Explorer</strong>: -O0と-O2の出力比較を日課にする</li><li><strong>VS逆アセンブリ</strong>: ブレーク中に Ctrl+Alt+D。レジスタ/メモリ/ コールスタックウィンドウとの併用</li><li>リリースビルドのデバッグ: 最適化でコード行と命令が一致しない現実</li></ul></li><li><strong>最適化されたコードの読み方</strong><ul><li>インライン展開で関数が消える、ループ回転、自動ベクトル化(SIMD命令の出現)</li><li>「変数がレジスタに置かれ、メモリに存在しない」ことがある</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>スタックフレーム</strong> ── ローカル変数・再帰・コールスタックの正体</li><li><strong>呼出規約(calling convention)</strong> ── 関数間の暗黙の契約。ABIの核</li><li><strong>Cの処理と命令列の対応を具体的に観察する</strong> ── 一行対数命令という固定対応はない</li><li><strong>最適化コードは原型を留めない</strong> ── だから計測とツールが要る</li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>リリース版のみのクラッシュをダンプ解析</td><td>逆アセンブリ+レジスタ読解</td></tr><tr><td>スタックオーバーフロー/スタック破壊バグ</td><td>スタックフレーム</td></tr><tr><td>「インライン化されてるか見て」</td><td>Compiler Explorerで確認</td></tr><tr><td>コールスタックウィンドウの仕組み</td><td>戻り番地の連鎖</td></tr><tr><td>クラッシュダンプの <code>RIP=0x0000...</code></td><td>命令ポインタ・関数ポインタ破壊</td></tr><tr><td>チート対策・逆解析耐性の議論</td><td>機械語読解</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li>Compiler Explorer(x64 msvc/clang)で以下を -O0 / -O2 両方で読め: <code>int add(int,int)</code> / <code>int sum(int* a, int n)</code> / 再帰フィボナッチ / <code>struct Vec3{float x,y,z;};</code> を返す関数</li><li>VSでC++プログラムをデバッグ実行し、ブレーク→逆アセンブリ表示→ F11で1命令ずつ実行しながらレジスタウィンドウでRAX等の変化を観察せよ。</li><li>意図的なスタックバッファオーバーフローを書き、戻り番地が壊れて クラッシュする様子を逆アセンブリ+メモリウィンドウで観察せよ。</li><li>関数呼び出し <code>f(1, 2.5f, ptr)</code> の直前でブレークし、RCX/XMM1/R8に 引数が入る様子を確認せよ(Windows呼出規約の実物)。</li><li>アセンブリだけの小関数(2数の最大値)をMASMまたはインラインで書き、 Cから呼び出せ(書くのはこれで最後。以後は読み専門でよい)。</li><li>Quake IIIの高速逆平方根を今こそ読み、各行を説明せよ(第1章の宿題回収)。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>『熱血アセンブラ入門』坂井弘亮 ── 多アーキテクチャを「読む」和書</li><li>Igor Zhirkov『低レベルプログラミング』── x64+C+ELFを繋ぐ良書</li><li>CS:APP 第3章 ── C→アセンブリ対応の決定版教材</li><li>MSDN「x64 calling convention」(公式・無料・必読)</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>Compiler Explorer</strong> (github.com/compiler-explorer) ── 主戦場</li><li><strong>Ghidra / x64dbg</strong> ── 触りだけ体験(逆解析の世界を知る)</li><li>musl libc の <code>memcpy</code> 等のasm実装(職人芸を眺める)</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>Creel &quot;x64 Assembly&quot; シリーズ(YouTube, 丁寧)</li><li>Matt Godbolt &quot;Bits Between the Bits&quot;(CppCon)── リンク/起動も繋がる</li><li>Handmade Hero の逆アセンブリを見る回(Casey Muratori)</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>自分のゲームコードのリリースビルド逆アセンブリ(最高の教材)</li><li>UE5 <code>FMemory::Memcpy</code> から辿るプラットフォーム別実装</li><li>DOOM(1993) <code>m_fixed.c</code>(固定小数点乗算のasm)── 歴史的教養として</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>RSP・RIP・RAXそれぞれの役割は?</li><li><code>call</code>命令は何をするか(2つの動作)。<code>ret</code>は?</li><li>Windows x64で整数引数4つはどのレジスタで渡るか? floatは?</li><li><code>mov eax, [rcx+rdx*4]</code> はC言語のどんな式に対応するか?</li><li>ローカル変数はどこに確保されるか。<code>&amp;var</code>が取れるのはなぜか。</li><li>リリースビルドでブレークポイントの行に止まらないことがあるのはなぜ?</li><li>コールスタックウィンドウはどんな仕組みで呼び出し履歴を表示しているか?</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>あなたが書くC++             命令列の説明例(Windows x64、最適化で変わる)</span></span>
<span class="line"><span>──────────────────────────────────────────────</span></span>
<span class="line"><span>player.pos.x += v * dt;  →  movss xmm0,[rbx+10h]</span></span>
<span class="line"><span>                            mulss xmm1,xmm2</span></span>
<span class="line"><span>                            addss xmm0,xmm1</span></span>
<span class="line"><span>                            movss [rbx+10h],xmm0</span></span>
<span class="line"><span>if (hp &lt;= 0) Die();      →  cmp dword ptr[rbx+20h],0</span></span>
<span class="line"><span>                            jg   skip</span></span>
<span class="line"><span>                            call Die</span></span>
<span class="line"><span>Update(dt);              →  call命令 → スタックに戻り番地</span></span>
<span class="line"><span>                            → RCXにthis, XMM1にdt (呼出規約)</span></span>
<span class="line"><span>──────────────────────────────────────────────</span></span>
<span class="line"><span>クラッシュ解析・最適化確認・チート解析は全部この層で行う</span></span>
<span class="line"><span>コールスタック表示、ブレークポイント(int3命令)もこの層の技術</span></span></code></pre></div><h2 id="記述の確認資料" tabindex="-1">記述の確認資料 <a class="header-anchor" href="#記述の確認資料" aria-label="Permalink to &quot;記述の確認資料&quot;">​</a></h2><ul><li><a href="https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf" target="_blank" rel="noreferrer">WG14 N1570: C11 committee draft (5.1.2.3, 6.2.4, 6.5, 6.7.2.1)</a></li><li><a href="https://eel.is/c++draft/intro.abstract" target="_blank" rel="noreferrer">C++ working draft: Abstract machine</a></li><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intel 64 and IA-32 Architecture / Optimization manuals</a></li></ul>`,30)])])}const m=a(o,[["render",s]]);export{u as __pageData,m as default};
